r=Report('05-agent-mediated-distribution','Agent-mediated discovery and transactions','AI is changing who presents the options. Completing the sale still depends on the business behind them.','US search and commerce evidence; platform architecture')
r.source('Pew: Google users and AI-summary clicks','https://www.pewresearch.org/short-reads/2025/07/22/google-users-are-less-likely-to-click-on-links-when-an-ai-summary-appears-in-the-results/','July 22, 2025; March browsing, April result reconstruction','Observed browsing from 900 US adults; 68,879 unique searches.','Queries were not randomized. Search results were reconstructed later and could differ from what the user originally saw.')
r.source('Adobe: Q2 2026 AI-sourced traffic insights','https://business.adobe.com/resources/sdk/.2026-q2-ai-traffic-report/q2-2026-adi-ai-sourced-traffic-insights.pdf','April 2026; traffic through March 2026','Adobe Analytics observations; separate consumer survey.','Customer-site coverage, referral attribution and user intent affect comparisons. Retail findings do not measure autonomous checkout volume.')
r.source('Shopify: how agentic commerce works','https://www.shopify.com/blog/how-agentic-commerce-works','June 18, 2026; Q1 2026 growth metrics','Platform-reported traffic, order growth and deployment status.','No absolute denominator supplied for the growth claims. AI-sourced orders include human-completed checkouts.')
r.source('Google: agentic-commerce launch and UCP','https://blog.google/products/ads-commerce/agentic-commerce-ai-tools-protocol-retailers-platforms/','January 11, 2026','Platform announcement.','Initial eligible-merchant rollout and forward-looking availability; not independent adoption or transaction data.')
r.source('Google: UCP updates','https://blog.google/products-and-platforms/products/shopping/ucp-updates/','March 19, 2026','Product capability announcement.','Cart, catalog and identity capabilities establish technical scope, not usage or commercial outcomes.')
r.source('Google Developers: under the hood of UCP','https://developers.googleblog.com/under-the-hood-universal-commerce-protocol-ucp/','January 11, 2026','Primary protocol explanation and reference implementation.','Illustrative integration; interoperability and merchant participation must be checked for a particular deployment.')
r.source('Walmart and Google: shopping in Gemini','https://corporate.walmart.com/news/2026/01/11/walmart-and-google-turn-ai-discovery-into-effortless-shopping-experiences','January 11, 2026','Retailer announcement of a planned experience.','Does not disclose transaction volume, conversion lift or the resulting split of customer economics.')
r.source('Visa: completed agent-initiated transactions','https://corporate.visa.com/en/sites/visa-perspectives/newsroom/visa-partners-complete-secure-agentic-transactions.html','December 18, 2025','Payment-network announcement of partner transactions.','Hundreds of completed transactions establish feasibility, not mass adoption, independent fraud performance or long-run unit economics.')
r.source('Visa Intelligent Commerce: developer capabilities','https://developer.visa.com/capabilities/visa-intelligent-commerce','Documentation checked September 21, 2026','Primary payment and authorization architecture.','Available functions and consent controls do not show usage or guarantee prevention of fraud and disputes.')
r.source('Cloudflare: measuring crawl-to-referral ratios','https://blog.cloudflare.com/ai-search-crawl-refer-ratio-on-radar/','July 1, 2025','Primary traffic-measurement methodology.','Cloudflare-covered sites; HTML requests and identifiable referer headers. Crawling is neither a citation nor a sale.')
r.source('Google Search Central: AI features and websites','https://developers.google.com/search/docs/appearance/ai-features','Documentation checked September 21, 2026','Primary guidance on search eligibility and measurement.','No special AI markup requirement does not mean ranking is predictable; visibility remains platform-dependent.')
r.section('brief','Executive brief','Discovery is moving faster than delegated buying.',p('There is convincing evidence that AI interfaces affect search behavior and send customers to merchants. There is also evidence of real agent-initiated payments. The scale and economics of those two developments are not yet the same.', 'lead')+brief([
('A citation may produce little traffic','Pew found clicks on traditional results in 8% of visits with an AI summary, versus 15% without. Clicks on a summary’s own source links occurred in only 1% of summary visits.'+cite(1)),
('Some arriving shoppers are valuable','Adobe reports retail AI referrals converting 42% better than non-AI referrals in March 2026. This compares different visitor groups; it does not prove the assistant caused the higher conversion.'+cite(2)),
('Growth is real; market share is missing','Shopify reports Q1 2026 AI traffic up 8× and AI-search orders nearly 13× year over year. Without absolute volumes, those numbers cannot establish dominance.'+cite(3)),
('Transaction infrastructure is taking shape','Google, Shopify, Walmart and payment networks are connecting discovery with catalogs, checkout and authorization. Merchant operations and user permission remain essential.'+cite(4,6,8))
])+note('<b>Definitions.</b> “AI-referred” means a customer arrives from an AI interface. “AI-assisted” can include research or comparison. “Agent-initiated” means software initiates a transaction under delegated authority. These categories overlap; none is a synonym for an unattended purchase.'))
r.section('evidence','Observed behavior','Less traffic for some publishers. Better traffic for some merchants.',r.chart('Traditional search-result click rate with and without an AI summary',[('No AI summary',15,'15%'),('AI summary present',8,'8%')],20,'Percent of Google search visits','Pew: 900 US adults, 68,879 unique March 2025 searches. Results reconstructed April 7–17. The 7-percentage-point gap is an association; query mix and reconstruction limit causal interpretation. This is not a retail conversion chart.',[1])+table('Different measures answer different commercial questions',['Evidence','Observed result','Boundary'],[
('Adobe retail referrals'+cite(2),'March 2026: conversion +42%, revenue per visit +37%, engagement +12%, relative to non-AI referrals.','Conditional on arriving at a measured merchant site. Does not count users who never leave the assistant.'),('Adobe travel referrals'+cite(2),'March 2026 conversion remained 14% below non-AI referrals.','The retail result is not universal across industries or purchase complexity.'),('Shopify platform growth'+cite(3),'Q1 2026: AI-driven traffic 8× and AI-search orders nearly 13× the prior year.','Growth from an undisclosed base; not a share of total sales.'),('Visa partner transactions'+cite(8),'Hundreds of completed agent-initiated transactions announced in December 2025.','Evidence that the payment path works in partner implementations; not a population adoption estimate.')
])+p('These findings can coexist. An assistant may answer a general question without sending a click, then refer a more decided buyer when a purchase requires a merchant. That is a plausible interpretation of the evidence, not a measured explanation. Publishers and sellers face different exposure even when the interface is the same.')+p('The current evidence does not justify a forecast that agents will capture a specific percentage of all commerce by a fixed year. It does justify measuring the new channel now, with separate counts for visibility, visits, orders and net contribution.'))
r.section('cases','Platform cases','The customer interface can move while the merchant keeps the work.',case('Commerce platform / Q1–Q2 2026','Shopify: distribute the catalog, preserve the transaction system', [('8×','year-over-year AI traffic growth, Q1'),('~13×','AI-search order growth, Q1'),('Human checkout','included in AI-channel commerce')], 'Shopify’s June account describes a shared catalog and integrations with AI surfaces. It identifies merchant-site checkout through an in-app browser for ChatGPT discovery and eligible direct checkout in Copilot. Inventory, tax, payment, fraud and fulfillment remain commerce responsibilities.'+cite(3), 'The platform can make millions of merchants reachable through a common integration. A new company selling basic feed connection must compete with this distribution. More promising gaps would involve specialized product data, difficult exceptions or measurable conversion failures.', 'These are Shopify’s own metrics and status descriptions. The 13× figure is not a count of autonomous purchases. No merchant-level margin or incrementality study is supplied.')+case('Retailer and platform / Announced January 2026','Walmart: bring the retail relationship into the assistant', [('Gemini','proposed discovery interface'),('UCP','announced connection standard'),('Not disclosed','completed-order volume or profit effect')], 'Walmart and Google announced a Gemini shopping experience connecting Walmart and Sam’s Club assortment with the retailer’s account and fulfillment capabilities. The announcement presents a planned integration rather than an independently measured commercial result.'+cite(7), 'A retailer with inventory, member benefits and delivery capacity can carry those advantages into a new interface. The assistant does not erase the value of a reliable physical operation. It may change who controls comparison and the initial customer interaction.', 'The case supports an architectural direction. It does not establish launch completion, incremental sales or how commercial terms divide value between retailer and platform.')+case('Payment network / Announced December 2025','Visa: distinguish authorized agents from ordinary bots', [('Hundreds','partner transactions completed'),('October 2025','Trusted Agent Protocol introduced'),('Consent','must connect the agent to user authority')], 'Visa reports completed partner transactions and a protocol intended to let merchants distinguish legitimate agents from malicious bots. Its Intelligent Commerce documentation describes payment credentials, authentication and controls for delegated buying.'+cite(8,9), 'Delegation creates a new operational question: did the software act within the user’s instructions? Identity, spending limits, transaction evidence and exceptions matter alongside recommendation quality. This offers infrastructure work, but also attracts incumbent payment providers.', 'Successful partner transactions do not establish population-scale reliability, a lower fraud rate or settled liability for every transaction type.'))
r.section('workflows','The transaction chain','A product description is not a purchasable offer.',flow('What must remain true from recommendation to fulfillment',[
('Discover','A customer states an intent. The interface selects or compares options using available product and service evidence.'),('Validate','Confirm the exact item, price, availability, eligibility, delivery and return terms at decision time.'),('Authorize','Obtain or verify the user’s mandate, payment authority and approval for relevant exceptions.'),('Complete and support','Create the order once, deliver it, reconcile payment and handle changes, returns and disputes.')
],'Analytical simplification of the commerce chain. A single protocol can connect stages, but it cannot ensure that a merchant’s underlying information or operations are correct.')+p('UCP describes a common interface for business capabilities such as checkout and product discovery, with separate payment instruments and handlers. Google’s documentation keeps the retailer as merchant of record. Its March update extends cart, catalog and identity functions. These standards reduce integration friction; they do not guarantee shelf availability, service quality or product suitability.'+cite(5,6))+table('Where an ordinary business may need to change',['Business record','Failure visible to an agent','Operational repair'],[
('Catalog or service description','Ambiguous specification, incompatible part or unsupported claim.','Structured attributes, stable identifiers and an accountable data owner.'),('Inventory or appointment capacity','A recommendation cannot actually be fulfilled.','Connect availability to the operating system; define reservations, expiry and substitution rules.'),('Pricing and terms','The quoted total omits shipping, eligibility, tax or a cancellation condition.','Expose the complete offer and verify it again before commitment.'),('Authorization and order handling','Duplicate purchase, wrong account or action outside the mandate.','Trace the approval, enforce limits and prevent duplicate execution.'),('After-sales service','No clear route to cancel, return, reschedule or resolve a dispute.','Preserve the order record and define human escalation and responsibility.')
])+p('For a small service business, the missing piece may be a truthful schedule and a clear scope of work. A machine-readable description cannot make a bespoke estimate instant or guarantee that an available technician is qualified. The opportunity is partly operational: make the promise precise enough that another system can safely act on it.'))
r.section('measurement','Measurement','Measure completed, profitable demand.',p('Cloudflare’s crawl-to-referral metric divides identifiable crawler HTML requests by attributable referred HTML visits. It is useful for understanding the exchange between content access and traffic. It does not count citations, unique shoppers or incremental purchases.'+cite(10))+table('A measurement ladder for an AI distribution channel',['Stage','Measure','Common mistake'],[
('Eligibility','Can the relevant system retrieve current information?','Treating crawl access as a guarantee of recommendation.'),('Visibility','Appearance and correctness across a defined set of representative customer questions.','Reporting an unstable, hand-picked prompt score as market share.'),('Arrival','Attributable visits or qualified inquiries, with missing attribution recorded.','Equating all “direct” traffic or AI-assistant mentions with AI acquisition.'),('Transaction','Completed paid orders, cancellations and fulfillment.','Counting created carts, recommendations or payment attempts as sales.'),('Incrementality','New contribution compared with an appropriate counterfactual.','Giving the channel credit for a customer who would have purchased anyway.'),('Relationship','Repeat orders, retention, support cost and permissioned customer contact.','Optimizing first-order conversion while losing future customer access.')
])+p('Google states that websites need no special additional optimization or markup to appear in its AI search features beyond the usual eligibility requirements. That is a useful check on claims that a proprietary “AI optimization” tag is mandatory. It does not make good product information unnecessary or guarantee visibility.'+cite(11))+p('A careful pilot would use stable definitions, compare similar products and include a control where practical. Track catalog changes, seasonality, promotions and platform changes. A before/after traffic rise during a platform rollout cannot by itself establish that a merchant’s optimization work caused it.'))
r.section('economics','Economics','High conversion does not settle channel economics.',p('Consider a hypothetical merchant with 1,000 monthly AI-referred visits, a 4% purchase rate, a $100 average order and $30 contribution per order before acquisition cost. The channel produces $4,000 revenue and $1,200 contribution. These inputs are assumptions, not Adobe’s measured conversion rate.')+table('Illustration: what could support an ongoing channel service?',['Scenario','Monthly contribution before service cost','After $600 monthly service cost'],[
('All 40 orders are incremental','$1,200','$600'),('Only half of 40 orders are incremental','$600','$0'),('All orders incremental; contribution falls to $20/order','$800','$200')
])+p('Setup costs, platform fees and incremental returns would lower those outcomes further. A traffic-growth chart cannot tell us which row applies. A viable provider must either serve enough contribution profit, improve the economics by enough, or deliver at a lower cost.')+p('The same distinction applies to a marketplace. If agents simplify comparison, a new intermediary may gain traffic but struggle to charge for a recommendation. Conversely, a provider that verifies stock, guarantees service or handles a difficult transaction can still supply value after discovery becomes cheap. Whether customers will pay for that value remains a segment-specific question.'))
r.section('implications','Opportunity hypotheses','The stronger openings sit close to a real transaction.',table('Potential beneficiaries and openings',['Position or need','Why it may matter','Company test'],[
('Reliable merchants with accurate operating data','Agents can compare and transact more easily when the offer is explicit and current.','Can better data increase profitable completed orders across several merchants?'),('Specialist catalog and availability infrastructure','Complex specifications and fragmented systems create work that generic feeds may not solve.','Does the integration remain valuable after Shopify or a vertical software vendor adds basic support?'),('Delegated transaction controls','Businesses need evidence of identity, authority, limits and successful execution.','Is there a recurring gap beyond payment-network and platform controls?'),('Publishers dependent on informational search','Answers delivered inside the interface may reduce visits.','Can distinctive data, a direct relationship or licensed access support an alternative revenue model?'),('Generic AI visibility agencies','Buyers may want help, but attribution and platform dependence are substantial.','Can the provider show incremental profit rather than a selected set of favorable answers?')
])+p('For the repository’s company ideas, a narrow transactional problem is more testable than “help every company be found by agents.” One example would be making a specialist distributor’s availability and compatibility data dependable enough for a purchase. Another would be enabling a service business to accept a qualified booking with explicit scope and exception handling. Both require proving demand and surviving platform bundling.'))
r.section('questions','What would change the view','Watch absolute adoption and the division of value.',table('Next evidence worth collecting',['Question','Useful evidence','Thesis weakens if…'],[
('How large is the channel?','Absolute visits, orders and contribution share by category and merchant size.','Growth remains concentrated in a tiny or subsidized base.'),('Who controls the relationship?','Actual contracts, account access, repeat-purchase behavior and support ownership.','Intermediary costs rise faster than merchant benefit.'),('Can transactions be delegated reliably?','Completion, unauthorized-action, cancellation, return and dispute rates on real orders.','Exception handling outweighs saved effort or users repeatedly revert to manual purchase.'),('Does specialist integration pay?','Paid deployment across comparable businesses, including upkeep after catalog changes.','Each merchant is bespoke or platform features eliminate the need.'),('Can improvement be attributed?','Controlled or matched channel tests with fulfillment and net margin included.','Visibility increases without incremental profitable demand.')
])+p('The near-term evidence supports channel experimentation and operational preparation. The longer-term company question is who can retain value when product discovery becomes easier: the interface, the merchant, the payment network, or a provider solving a transaction problem none of them handles well.'))
r.evidence.append(dict(title='AI channel contribution illustration',kind='illustrative',assumptions=dict(monthly_visits=1000,conversion=.04,average_order=100,contribution_before_acquisition=30,monthly_service_cost=600),cases=[dict(incrementality=1,contribution_per_order=30,net=600),dict(incrementality=.5,contribution_per_order=30,net=0),dict(incrementality=1,contribution_per_order=20,net=200)],source_ids=[]))
r.save()
